/**
 * Renders the node subgraph's schema from the discovered type names. This file is
 * the only place the shape of that schema is decided; the output is committed as
 * `schema.graphql` and must never be edited by hand.
 */
export function renderNodeSubgraphSchema(typeNames: readonly string[]): string {
  const stubs = typeNames
    .map(
      (typeName) =>
        `type ${typeName} implements Node @key(fields: "id", resolvable: false) {\n  id: ID!\n}\n`,
    )
    .join("\n");

  return [
    "# GENERATED by `pnpm graph:update` from the other subgraphs' schemas. Do not edit.",
    "# See docs/decisions/0004-node-subgraph.md.",
    "",
    'extend schema @link(url: "https://specs.apollo.dev/federation/v2.9", import: ["@key"])',
    "",
    "interface Node {",
    "  id: ID!",
    "}",
    "",
    "type Query {",
    "  node(id: ID!): Node",
    "}",
    "",
    stubs,
  ].join("\n");
}
